\begin{proposition}[Backward induction]\label{game:thm:adequacy}
Every game has a full pure SPE profile, and
$\den{\at i}=\{i\}$, $\den{G\ch r H}=\den G\ow r\den H$.
\end{proposition}

\begin{proposition}[Neutral union]\label{game:thm:union}
For pairwise distinct $r,s,t$,
\begin{equation}\label{game:eq:union}
 J(x,y)=(x\ow r y)\ow t(x\ow s y)=x\cup y.
\end{equation}
Consequently every member of $\Pow$ is the value of a game.
\end{proposition}

\begin{proposition}[Player views]\label{view:thm:view}
$S\equiv_k T$ exactly when $S,T$ agree on whether they contain $k$ and on whether they equal $\{i\}$, for each $i\ne k$. So there are exactly $K+1$ classes:
$\pv$, the sets containing $k$; $a_i$, the atom $\{i\}$, for each $i\ne k$; and $\nv$, the ambiguous sets omitting $k$.
\end{proposition}

\begin{lemma}[Permutation provenance on a status cell]\label{sym:lem:provenance}
On every fixed status cell, a term denotes
\begin{equation}\label{sym:eq:provenance}
 C\ \cup\ \bigcup_j\ \bigcup_{\pi\in P_j}\pi S_j,
\end{equation}
where $S_j$ is the value of $x_j$, $C\subseteq I$, only ambiguous input variables occur in the union,
and every $P_j$ is a finite, possibly empty, set of permutations.
\end{lemma}

\begin{theorem}[Pair countervaluations]\label{sym:thm:pairs}
If an equation between terms of $\mathbf A^{\rm sym}$ fails, it fails at a valuation in which every variable has one or two possible winners.
\end{theorem}

\begin{theorem}[Idempotent elimination]\label{gen:thm:core}
A term is idempotent if and only if it has no winner leaves and every variable occurrence has identity accumulated permutation. Consequently the idempotent term operations are exactly those of $\mathbf C$, and an equivalent term can be extracted in polynomial time.
\end{theorem}

\begin{theorem}[One common source]\label{gen:thm:source}
Fix valuations $v_e$ and pairwise disjoint regions $W_e\subseteq I$. If $t(v_e)\subseteq W_e$ for every $e$, then one source occurrence of $t$ has its value inside $W_e$ in every valuation simultaneously. With at least two regions, it is a variable occurrence.
\end{theorem}

\begin{corollary}[Determinacy]\label{gen:cor:determinacy}
An idempotent atom-preserving term projects one input on atomic valuations.
\end{corollary}

\begin{theorem}[Binary atom-preserving operations]\label{reset:thm:binary}
The binary atom-preserving operations of $\mathbf C$ are exactly $x$, $y$, $x\del y$, and $y\del x$.
\end{theorem}

\begin{proposition}[Canonical tables]\label{reset:thm:three}
Two reset terms are equal on all valuations if and only if their tables agree, and this can be tested on the fixed chain
$Z=\{a\}\subset U=\{a,b\}\subset T=\{a,b,c\}$. So equality is polynomial, and reset has the same identities for every $K$.
\end{proposition}

\begin{proposition}[Finite basis, after Freese et al.]\label{reset:thm:basis}
An equation between reset terms holds on all valuations if and only if it follows in equational logic from
\begin{alignat*}{2}
 &\text{(R1)}\quad x\del x=x,\qquad&&\text{(R2)}\quad (x\del y)\del x=y\del x,\\
 &\text{(R3)}\quad (x\del y)\del y=x\del y,\qquad&&\text{(R4)}\quad x\del((x\del y)\del z)=x\del(y\del z),\\
 &\text{(R5)}\quad ((x\del y)\del z)\del y=(x\del z)\del y,\qquad&&\text{(R6)}\quad x\del(y\del z)=y\del(x\del z).
\end{alignat*}
\end{proposition}

\begin{theorem}[Antimatroid representation]\label{reset:thm:anti}
Reset term functions on a fixed set of inputs correspond bijectively to antimatroids with one feasible singleton on nonempty sets of those inputs.
\end{theorem}

\begin{theorem}[Pair dichotomy]\label{thm:raw-pairs}
Fix $K$. For a signature chosen from $\{\star_r:r\in I\}\cup\{\cup,\del\}$, equation validity is polynomial if the signature has at most one operation, and coNP-complete otherwise.
\end{theorem}

\begin{corollary}[Equational complexity]\label{gen:thm:complexity}
Equational validity in $\mathbf C$, $\mathbf A$, and $\mathbf A^{\rm sym}$ is coNP-complete, at every fixed $K$ and with $K$ as part of the input.
\end{corollary}

\begin{lemma}[Root status]\label{owner:lem:root}
A term is ambiguous, or equal to $\{r\}$, exactly when its root variable is.
\end{lemma}

\begin{proposition}[Guard completeness]\label{owner:thm:guards}
If all $H$ indices in $s,t$ belong to $\{k,a\}$, then $k\in s$ implies $k\in t$ on all valuations if and only if every guard of $\Gamma_k(s)$ is covered by a guard of $\Gamma_k(t)$. A failed comparison has an explicit countervaluation with at most two winners per input, using three roles.
\end{proposition}

\begin{theorem}[One-table completeness]\label{owner:thm:one-table}
Terms in $\{\del,H_a\}$ are equal on all valuations if and only if their guard lists for any one outsider cover each other. So equation validity is polynomial, uniformly in $K$.
\end{theorem}

\begin{theorem}[Minimum generator]\label{owner:thm:four}
For every role $a$, $(\Pow;\del,H_a)$ has exactly the identities of $\mathbf F$, and no smaller algebra generates this theory.
\end{theorem}

\begin{theorem}[Finite equational basis]\label{owner:thm:basis-main}
The one-owner theory has a basis of forty identities using at most
six variables. Every basis needs an identity with at least four
variables.
\end{theorem}

\begin{corollary}[Owner-count dichotomy]\label{owner:cor:complexity}
Fix $K$ and $R\subseteq I$. For reset with $H_r$, $r\in R$, equation validity is polynomial when $|R|\leq1$ and coNP-complete when $|R|\geq2$. For an observer $k$, the implication $k\in s\Rightarrow k\in t$ on all valuations, and the corresponding equivalence, are polynomial when $|R\setminus\{k\}|\leq1$ and coNP-complete when $|R\setminus\{k\}|\geq2$.
\end{corollary}

\begin{theorem}[No finite basis]\label{core:thm:no-basis}
For every $K\geq3$, $\mathbf C$ has no finite equational basis. Indeed, for every $n$ there is a finite algebra that satisfies every identity of $\mathbf C$ in $n$ variables but not all of them.
\end{theorem}

\begin{theorem}[No finite winner algebra]\label{se:thm:infinite}
For all $n,m\geq0$,
\[
 \operatorname{Win}(\mathcal E(F_m[G_n]))=
 \begin{cases}
 \{a,b\},&n<m,\\
 \{a,b,c\},&n=m,\\
 \{a,c\},&n>m,
 \end{cases}
\]
where $\operatorname{Win}(P)$ is the set of roles with positive probability in some member of $P$. So no finite-valued compositional semantics of the round language can preserve even player $c$'s possible-win observation, already with three roles and Boolean commitments.
\end{theorem}

\begin{proposition}[Occurrence lower bound]\label{game:thm:lower}
Suppose $K\geq3$. In the syntax of owned binary choices and arbitrary
nonempty ground constants, any term that denotes $x\cup y$ for every
$x,y\in\Pow$ contains at least two occurrences of $x$ and at least two
occurrences of $y$. Hence three binary nodes are optimal.
\end{proposition}

\begin{proposition}[No Boolean representation]
\label{cor:no-boolean-product}
For $K\ge3$, the algebra $\Pow$ of owned choices has no injective homomorphism into a
product of Boolean algebras in which each owned operation acts in each
coordinate as either meet or join.
\end{proposition}

\begin{corollary}[Faithful family of small perspectives]\label{view:cor:product}
The canonical map
\[
 \A\longrightarrow\prod_{k\in I} C_k,\qquad
 S\longmapsto([S]_{\equiv_k})_{k\in I}
\]
is an injective homomorphism and is onto each factor. Thus the
$2^K-1$-valued algebra has a subdirect representation by $K$ factors,
each of size $K+1$.
\end{corollary}

\begin{proposition}[Reduct test domains]\label{view:thm:tests}
A domain $D$ is complete exactly when:
\begin{enumerate}
\item every singleton $\{i\}$ belongs to $D$;
\item for every $k$, some ambiguous $F\in D$ omits $k$.
\end{enumerate}
The second condition says that the intersection of the ambiguous members
of $D$ is empty, with the intersection of an empty family taken as $I$.
\end{proposition}

\begin{corollary}[Sharp size]\label{view:cor:optimal}
The minimum size of a complete fixed test domain is
\[
 \begin{cases}6,&K=3,\\K+2,&K\geq4.\end{cases}
\]
For three roles, take every singleton and every pair. For four or more,
take every singleton and any two disjoint pairs.
\end{corollary}

\begin{lemma}[Resetting atomic inputs]\label{sym:lem:reset}
If a unary term function $F$ is extensive, start with $U(x)=F(x)$ and
successively replace $U(x)$ by $U(x)\ow i x$, for each $i\in I$. This gives a term
$\operatorname{Reset}(F)$ which fixes all singletons and agrees with $F$
on every ambiguous input.
\end{lemma}

\begin{proposition}[Atomic functions]\label{gen:thm:S2}
At every positive arity, the functions induced by atom-preserving terms
are exactly the essentially unary or at most two-valued functions.
This is the known clone $S_2$.
\end{proposition}

\begin{lemma}[One-constant rigidity]\label{reset:lem:rigidity}
A unary owned-choice expression whose only constant is $\{r\}$ is
either constantly $\{r\}$ or inflationary: it contains its input on
every valuation. Consequently, returning $\{r\}$ at any other singleton
$\{q\}$ already forces it to be constant.
\end{lemma}

\begin{lemma}[Resolution and selection]\label{reset:lem:selection}
A reset term is ambiguous exactly when its root input is ambiguous.
There is a selector $E_t:2^N\to2^N$ with
\begin{align*}
 E_{x_j}(B)&=\{j\},\\
 E_{s\del t}(B)&=E_t(B)\cup
 \begin{cases}E_s(B),&\rho(t)\in B,\\\varnothing,&\rho(t)\notin B,\end{cases}\\
 t(S)&=\bigcup_{j\in E_t(B)}S_j.
\end{align*}
Every selector is monotone, always selects its root, and selecting
position $j$ is independent of whether $j$ itself belongs to $B$.
\end{lemma}

\begin{corollary}[Minimum finite generator]\label{reset:cor:generator}
The three-element algebra generates the common variety of all reset
algebras on $\Pow$ for $|I|\geq3$, and no smaller algebra generates
that variety.
\end{corollary}

\begin{proposition}[Realizability]\label{reset:thm:synthesis}
A table is the canonical table of a reset term exactly when:
\begin{enumerate}
\item $\mathcal G_r=\{\varnothing\}$ and no other antichain contains
$\varnothing$;
\item every member of $\mathcal G_j$ omits $j$;
\item every member of every antichain is constructible.
\end{enumerate}
Recognition is polynomial in the table description. A realizable
table with $M$ prerequisites on $n$ input positions has a term
realization of size $O(nM)$.
\end{proposition}

\begin{proposition}[Minimal clone]\label{reset:thm:minimal}
Every nonprojection reset term has a binary identification minor equal
to reset. Hence its term clone is minimal.
\end{proposition}

\begin{proposition}[Reset with union]\label{thm:owner-free-hardness}
For every fixed $K\geq3$, equation validity for the signature
$\{\del,\cup\}$ on $\Pow$ is coNP-complete. It uses no constants,
owner names, or internal role switches.
\end{proposition}

\begin{proposition}[Two guarded owners]\label{thm:H-hardness}
For $K\geq3$ and distinct $a,b\in I$, equation validity for
$\{H_a,H_b\}$ on $\Pow$ is coNP-complete, without constants.
\end{proposition}

\begin{proposition}[Dependence on the number of roles]\label{thm:colouring-theories}
For every $K\geq3$,
$\operatorname{Eq}(\mathcal B_{K+1})\subsetneq
 \operatorname{Eq}(\mathcal B_K)$.
\end{proposition}

\begin{proposition}[Properties of round values]\label{se:prop:round-values}
Each value set is nonempty, compact, and semialgebraic over the rationals. The round operators are monotone in their continuation sets and commute with role renaming. Reordering the private commitments within a round preserves the value set.
\end{proposition}

\begin{corollary}[Public mixed-support conservativity]\label{se:cor:public}
On finite public owned-choice trees,
$\operatorname{Win}(\mathcal E(G))=\den G$. Allowing mixed sequential
equilibria adds no possible winner to the pure SPE observation.
\end{corollary}

\begin{proposition}[Parallel sum]\label{se:prop:parallel}
The constructor $D$ denotes
\[
 x\parallel y=
 \begin{cases}xy/(x+y),&x+y>0,\\0,&x=y=0.\end{cases}
\]
It is associative, commutative, monotone, and zero-absorbing. On the
unit interval it distributes over both $\min$ and $\max$.
\end{proposition}

\begin{proposition}[Rational values]\label{se:thm:rational}
The scalar values generated by the winner leaves, role exchange, and
$D$ are exactly $\mathbb Q\cap[0,1]$. In fact $C$ and
$U(x)=x\parallel1=x/(1+x)$ suffice with the leaves.
\end{proposition}

\begin{corollary}[Decidable scalar equations]\label{se:cor:decidable}
Equations in $0,1,C,\parallel,\min,\max$ hold on rational scalar
values exactly when they hold on the real unit interval. Their validity
is decidable by real quantifier elimination.
\end{corollary}

\begin{corollary}[Scalar full abstraction]\label{se:cor:scalar}
For closed components in the rational scalar fragment with the same
active pair, equality of scalar values is exactly contextual
equivalence for possible SE winners in the three-role round language.
It suffices to observe the third role's possible victory.
\end{corollary}

\begin{proposition}[Two disjoint policies]\label{selective:prop:disjoint}
For disjoint nonempty $D,D'\subseteq I$ and $K\geq3$, equation validity for
$\{R_D,R_{D'}\}$ is coNP-complete, without constants.
\end{proposition}

\begin{corollary}[Two owners, polynomial equality]\label{selective:cor:G}
For distinct $a,b$ and every $K\geq3$, the language $\{\del,G_{a,b}\}$
has polynomial equation validity. Either owner's possible-win observation,
compared on all valuations, suffices for full equation equality.
\end{corollary}

\begin{theorem}[Covering, overlapping policies]\label{selective:thm:covering}
Suppose $D,E$ are incomparable, overlap, and satisfy $D\cup E=I$.
If $K\geq4$, equation validity for $\{\del,R_D,R_E\}$ is polynomial.
One observer whose atomic pattern has a second representative is
equation-complete.
\end{theorem}

\begin{proposition}[Empty common intersection]\label{selective:prop:empty-inter}
Fix a finite family of nonempty policies with empty total intersection.
Equation validity for its rooted operations is coNP-complete at each
fixed $K\geq3$. Three pairwise-overlapping policies already suffice.
\end{proposition}

\begin{proposition}[Strong Kleene logic]\label{two:prop:kleene}
On the chain $\bot<m<\top$, the operations $\star_a$ and $\star_b$ are maximum and minimum, and the role switch is the order-reversing involution fixing $m$.
\end{proposition}

\begin{proposition}[Term functions]\label{two:prop:terms}
The term functions of $\mathbf A^{\rm sym}$ are exactly the normal monotone functions. With a constant $m$ added, they are exactly the monotone functions.
\end{proposition}

\begin{proposition}[Presentation]\label{two:prop:basis}
The identities of $\mathbf C$ are those of distributive lattices, and those of $\mathbf A$ are those of bounded distributive lattices; in both cases the two atoms decide them. The identities of $\mathbf A^{\rm sym}$ follow in equational logic from the bounded distributive lattice laws, $\lnot\lnot x=x$, $\lnot(x\land y)=\lnot x\lor\lnot y$, $\lnot\bot=\top$, and
\begin{equation}\label{two:eq:kleene}
 x\land\lnot x\leq y\lor\lnot y,
\end{equation}
and all three values are needed to test them.
\end{proposition}

\begin{proposition}[Complexity]\label{two:prop:complexity}
For a signature chosen from $\{\star_a,\star_b,\cup,\del\}$, equation validity is coNP-complete if the signature contains two of $\star_a,\star_b,\cup$, and polynomial otherwise. Validity in $\mathbf C$, $\mathbf A$, and $\mathbf A^{\rm sym}$ is coNP-complete.
\end{proposition}

\begin{proposition}[Rounds]\label{two:prop:rounds}
$\operatorname{Win}(\mathcal E(\mathsf R))=S_a\cup S_b=(S_a\lor m)\land S_b$.
\end{proposition}

\begin{proposition}[Unary normal forms]\label{game:thm:unary}
The unary term functions are exactly the nonempty constant functions and
the functions~\eqref{game:eq:normal}. The regular parameters $C,(E_i)$ are
unique. The only overlap with the constant functions is the constant
function $I$.
\end{proposition}

\begin{corollary}[Count and a small test set]
There are exactly
\begin{equation}\label{game:eq:count}
  (1+2^{K-1})^K+2^K-2
\end{equation}
unary term functions. Equality of two unary functions is determined by
their values on singleton and two-element input sets.
\end{corollary}

\begin{proposition}[Canonical status forms]\label{view:thm:normal}
This normalization is sound on each status cell. Its final pair $(C,\Lambda)$
is uniquely determined by the term function on that cell. Consequently
the table of these pairs over all $(K+1)^n$ statuses is a canonical
representation of any $n$-variable term function.
\end{proposition}

\begin{theorem}[All unary term operations]\label{sym:thm:unary}
Every unary term function is either a constant or has the following
unique normal form:
\begin{equation}\label{sym:eq:unary}
 f(S)=\begin{cases}D_i,&S=\{i\},\\F_p(S),&|S|\geq2,\end{cases}
\end{equation}
where $p$ is a partial permutation and the nonempty rows satisfy
\[
 \begin{array}{ll}
 \{p(i)\}\subseteq D_i\subseteq C_p\cup\{p(i)\},
       &i\in\operatorname{dom}(p),\\
 \varnothing\ne D_i\subseteq C_p,
       &i\notin\operatorname{dom}(p).
 \end{array}
\]
Every such normal form is realized by a term. The only constant also
in this family is the constant $I$.
\end{theorem}

\begin{proposition}[An ambiguity-action quotient]\label{sym:thm:monoid}
The $745$ unary term operations preserving $I$ form a monoid under
composition. Sending the normal form $(p,D)$ to $p$ is a surjective
monoid homomorphism onto $\mathcal I_I$.
\end{proposition}

\begin{proposition}[Ambiguity quotient]\label{gen:thm:quotient}
Let $\mathcal M_I$ be the monoid of unary term functions fixing $I$.
Restriction to $\mathcal A_I$ is a surjective monoid homomorphism
$\mathcal M_I\twoheadrightarrow\mathcal Q_I$.
\end{proposition}

\begin{proposition}[Matching criterion]\label{gen:thm:matching}
A collection of canonical rows belongs to $\mathcal Q_I$ exactly when
every prescribed edge belongs to a perfect matching of $H$. If all rows
are constant, it always belongs.
\end{proposition}

\begin{proposition}[Canonical composition]\label{gen:thm:composition}
For outer rows $A$ and inner rows $B$, the composite row at $k$ is:
\begin{enumerate}
\item $*$ if $A_k=*$ or some $i\in A_k$ has $B_i=*$;
\item otherwise $\bigcup_{i\in A_k}B_i$, changed to $*$ if that union
has at least $K-1$ elements.
\end{enumerate}
This computes composition in time polynomial in $K$ on descriptions of
$O(K^2)$ bits.
\end{proposition}

\begin{lemma}[Relative reset]\label{gen:lem:relative}
\[
 \Delta(A,B)=
 \begin{cases}B,&|B|=1,\\A\cup B,&|B|\geq2.\end{cases}
\]
Its value is independent of the enumeration of owners. It is
idempotent and equivariant.
\end{lemma}

\begin{theorem}[Two-permutation fibers]\label{gen:thm:cycles}
Fix $K\geq4$ and the ambiguity action $S\mapsto S\cup\sigma S$.
The choices on different cycles of $\sigma$ are independent.
On a cycle of length $m$ the permitted atomic tables are exactly:
\begin{itemize}
\item for $m=1$, its fixed singleton;
\item for $m=2$, every word in $\{0,1,?\}^2$;
\item for $m\geq3$, every word in $\{0,?\}^m$ or $\{1,?\}^m$,
and the $m$ words with $0$ at $r$, $1$ at $\sigma^{-1}(r)$,
and $?$ elsewhere.
\end{itemize}
Consequently the fiber size is
\[
 \prod_{C\text{ a cycle of }\sigma}g(|C|),\qquad
 g(1)=1,\quad g(2)=9,\quad g(m)=2^{m+1}+m-1\ (m\geq3).
\]
An arbitrary action $p[S]\cup q[S]$ is covered by normalizing the output
with $p^{-1}$ and taking $\sigma=p^{-1}q$.
\end{theorem}

\begin{lemma}
Every term function is monotone for inclusion on nonempty winner sets.
\end{lemma}

\begin{proposition}[Conservative presentation]\label{reset:thm:forest}
For a conservative algebra, the following are equivalent:
\begin{enumerate}
\item it satisfies every reset identity;
\item it satisfies the two equations
\begin{align}
 (x\del y)\del x&=y\del x,\label{reset:eq:absorb}\\
 x\del(y\del z)&=y\del(x\del z);\label{reset:eq:left-comm}
\end{align}
\item it has form \eqref{reset:eq:forest-op} for a unique forest order.
\end{enumerate}
The order is recovered by
$x\leq_P y$ iff $x\del y=y\del x=y$.
\end{proposition}

\begin{lemma}[Closure constructions]\label{reset:lem:closures}
The reset variety is closed under the following constructions:
\begin{enumerate}
\item adjoin one new element absorbing on both sides;
\item take a disjoint union of models, using the component operation
within a component and returning the right argument across components.
\end{enumerate}
\end{lemma}

\begin{lemma}[Forest membership]\label{reset:lem:forest-membership}
Every forest-order operation belongs to the reset variety.
\end{lemma}

\begin{proposition}[Comb monolith]\label{reset:thm:comb}
The comb is subdirectly irreducible. Its least nonidentity congruence
has the single nonsingleton class $\{a,b_0\}$.
\end{proposition}

\begin{corollary}[Known residual largeness, explicit comb witnesses]\label{reset:cor:residual}
The reset variety, equivalently $\operatorname{V}(G_3^{\rm op})$, has
subdirectly irreducible models of size $2n+1$ for every $n\geq1$, and
of every infinite cardinality. In particular, it has no cardinal bound
on the sizes of its subdirectly irreducible members.
\end{corollary}

\begin{definition}[Public script]
A well-formed script is generated by
\begin{equation}
 G ::= \End\langle R_i\rangle_{i\in\Roles}
       \mid \Q_r(x:A).H,
 \qquad r\in\Roles,
 \label{dep:eq:2}
\end{equation}
with formation rules
\begin{equation}
 \frac{(\Gamma\vdash R_i:\U)_{i\in\Roles}}
      {\Gamma\vdash\End\langle R_i\rangle_i:\Script}
 \qquad
 \frac{\Gamma\vdash A:\U\qquad\Gamma,x:A\vdash H:\Script}
      {\Gamma\vdash\Q_r(x:A).H:\Script}.
 \label{dep:eq:3}
\end{equation}
The binder introduces one value of $A$, owned by $r$, into every endpoint's
continuation context. At $\End$, the endpoints return their respective results;
the complete result record is exported at a public return boundary.
No endpoint sees the other terminal returns before supplying its own.
Thus \emph{public} describes the choice binders; a nontrivial terminal return
interface is a simultaneous decision stage, made explicit in
\cref{sec:composition}.
\end{definition}

\begin{definition}[Local interpretation]
For $i\in\Roles$, define the data type $\Local{i}{G}$ by
\begin{equation}
 \Local{i}{\End\langle R_j\rangle_j}=R_i,
 \qquad
 \Local{i}{\Q_r(x:A).H}=
 \begin{cases}
   \displaystyle\sum_{x:A}\Local{i}{H},&i=r,\\[3pt]
   \displaystyle\prod_{x:A}\Local{i}{H},&i\ne r.
 \end{cases}
 \label{dep:eq:4}
\end{equation}
An endpoint term $\Gamma\vdash p:G@i$ is a term of $\D$ of type
$\Local{i}{G}$, retaining $G$ and $i$ as its interface annotation.
\end{definition}

\begin{lemma}[Local interpretation commutes with substitution]
\label{lem:substitution}
For $\Gamma\vdash G:\Script$ and $\theta:\Delta\to\Gamma$,
\begin{equation}
 \Local{i}{G[\theta]}\equivdef\Local{i}{G}[\theta].
 \label{dep:eq:8}
\end{equation}
Consequently, $\Gamma\vdash p:G@i$ implies
$\Delta\vdash p[\theta]:G[\theta]@i$.
\end{lemma}

\begin{definition}[Trace and return family]
The trace type is
\begin{equation}
 \Trace(\End\langle R_i\rangle_i)=\Unit,
 \qquad
 \Trace(\Q_r(x:A).H)=\sum_{a:A}\Trace(H[a/x]).
 \label{dep:eq:9}
\end{equation}
For $t:\Trace(G)$, define the terminal return family by
\begin{equation}
 \Ret_i^{\End\langle R_j\rangle_j}(\star)=R_i,
 \qquad
 \Ret_i^{\Q_r(x:A).H}(a,t)=\Ret_i^{H[a/x]}(t).
 \label{dep:eq:10}
\end{equation}
The complete execution type is
\begin{equation}
 \Exec(G):=\sum_{t:\Trace(G)}\prod_{i\in\Roles}\Ret_i^G(t).
 \label{dep:eq:11}
\end{equation}
\end{definition}

\begin{definition}[Execution]
\label{def:execution}
Define $\Run_G(\vecp):\Exec(G)$ recursively. At a terminal,
\begin{equation}
 \Run_{\End\langle R_i\rangle_i}(\vecp)
       :=(\star,(p_i)_i).
 \label{dep:eq:12}
\end{equation}
At $G=\Q_r(x:A).H$, destruct $p_r$ as $(a,u_r)$ and put
\begin{equation}
 q_i:=
 \begin{cases}
   u_r,&i=r,\\
   p_i(a),&i\ne r.
 \end{cases}
 \label{dep:eq:13}
\end{equation}
If $\Run_{H[a/x]}(\vec q)=(t,\vec z)$, return
$((a,t),\vec z)$.
\end{definition}

\begin{lemma}[Dependent interaction]
\label{thm:interaction}
For every well-typed profile $p_i:G@i$, execution is well typed at $\Exec(G)$.
In particular, if $\Run_G(\vecp)=(t,\vec z)$, then
$z_i:\Ret_i^G(t)$ for every $i$.
\end{lemma}

\begin{corollary}[Subject reduction for complete connections]
\label{cor:preservation}
A communication step \eqref{dep:eq:14} preserves the typing of all residual endpoints at
one common residual script. Every recorded trace prefix is well typed.
\end{corollary}

\begin{lemma}[Endpoint transport]
\label{lem:role-transport}
$\Local{\pi(i)}{\pi G}\equivdef\Local{i}{G}$.
\end{lemma}

\begin{lemma}[Equivariance]
\label{thm:equivariance}
For every well-typed profile,
\begin{equation}
 \Run_{\pi G}(\pi\vecp)=\pi_*\Run_G(\vecp).
 \label{dep:eq:16}
\end{equation}
Role transport also takes each communication step to a communication step.
\end{lemma}

\begin{definition}[Boundary sequencing]
If $G$ is a conversation in $\Gamma$ and
$H$ is a conversation in $\Gamma,z:\Exec(G)$, write $G\mathbin{\triangleright_z}H$
for their boundary sequence. A plan for role $i$ consists of
\begin{equation}
 \Local{i}{G\mathbin{\triangleright_z}H}
   :=\Local{i}{G}\times\prod_{e:\Exec(G)}\Local{i}{H[e/z]}.
 \label{dep:eq:17}
\end{equation}
Write its two components as $(p_i,q_i)$.
Execute $G$ with $\vecp$, obtaining $e$, then execute $H[e/z]$ with
$(q_i(e))_i$. Retain both execution records:
\begin{equation}
 \Exec(G\mathbin{\triangleright_z}H)
       :=\sum_{e:\Exec(G)}\Exec(H[e/z]).
 \label{dep:eq:18}
\end{equation}
\end{definition}

\begin{proposition}[Sequential execution]
\label{prop:sequence}
The composite is well typed, and its execution satisfies
\begin{equation}
 \Run_{G\triangleright H}(\vecp,\vec q)
   =\bigl(e,\Run_{H[e/z]}((q_i(e))_i)\bigr),
 \qquad e=\Run_G(\vecp).
 \label{dep:eq:19}
\end{equation}
\end{proposition}

\begin{lemma}[Associativity of public boundary composition]
\label{thm:associativity}
For $G$, $H(e)$, and $J(e,f)$, the two bracketings of sequential composition
have canonically isomorphic endpoint-plan and execution types at extensional
interface equality. Under those isomorphisms their executions agree.
\end{lemma}

\begin{lemma}[Phase preservation]
\label{lem:phase-preservation}
A well-formed protocol implementation and a well-typed store advance to a
well-formed phase and a well-typed store.
\end{lemma}

\begin{lemma}[Binding across arbitrary continuations]
\label{prop:binding}
Fix a legal history ending with the binding of $c$ to $a$. Any two legal
extensions of that history, even using different later implementations,
publish $a$ whenever they successfully publish $c$.
\end{lemma}

\begin{lemma}[Composition of view-respecting maps]
\label{lem:view-composition}
Such maps include identities, are closed under composition, and preserve
the uniformity of a policy pulled back along them.
\end{lemma}

\begin{lemma}[Characterization of common readout knowledge]
\label{thm:common-knowledge}
For $p:W\to P$, the fact $p=p(h)$ is common knowledge among $S$ at every
$h\in W$ if and only if
\begin{equation}
 \forall i\in S,\quad
 V_i(h)=V_i(h')\ \Longrightarrow\ p(h)=p(h').
 \label{dep:eq:25}
\end{equation}
\end{lemma}

\begin{proposition}[No three-variable basis]\label{owner:prop:four-variables}
The equational theory of $\{\del,H_a\}$ is not axiomatizable by
identities using at most three variables, even by an infinite set of
such identities. A four-element algebra satisfies all its
three-variable identities but fails the valid identity
\begin{equation}\label{owner:eq:root-expansion}
 H_a(u\del r,y,z)
   =(u\del r)\del H_a(r,y,z).
\end{equation}
Consequently every equational basis contains an identity with at
least four variables.
\end{proposition}

\begin{lemma}[Two-source absorption]\label{owner:lem:two-source}
Let $W$ be a join of word values. Suppose $P(0)\leq W$ is already
derivable, and each of the two new source guards of $P(C_{ab})$
is covered by a guard of $W$. Then $P(C_{ab})\leq W$ is derivable
from the forty identities.
\end{lemma}

\begin{theorem}[Conservative presentation]\label{owner:thm:conservative-basis}
For an algebra $(C,\del,h)$ in which both operations are conservative,
the following are equivalent:
\begin{enumerate}
\item it satisfies every identity of $\mathbf F$;
\item it satisfies $\Sigma$.
\end{enumerate}
This holds for finite and infinite carriers. Omitting (R1), (R3),
(R4), and (R5) leaves thirteen equations with the same relative
completeness. Each uses at most four variables, and this variable
bound is optimal within the conservative class.
\end{theorem}

\begin{proposition}[The relative presentation is not a full basis]
\label{owner:prop:relative-not-full}
There is a four-element algebra satisfying $\Sigma$ that fails the
valid three-variable identity
\begin{equation}\label{owner:eq:insert-root}
 h(x,y,z)=h(x,x\del y,z).
\end{equation}
\end{proposition}

\begin{proposition}[A nonconservative irreducible model]
\label{owner:prop:nonconservative-si}
The variety generated by $\mathbf F$ has a four-element subdirectly
irreducible member whose reset operation is not conservative.
\end{proposition}

\begin{proposition}[A grid countermodel]\label{core:prop:grid-countermodel}
Fix $K\geq3$ and $r,s\geq2$. There are a finite algebra
$C_{r,s}\in\operatorname V(\mathbf C_K)$ and a reflecting element
$e\in C_{r,s}$ such that $(C_{r,s})_{\leq e}=\{T,S,e\}$ for two elements
$T,S$ with
\[
 e\star_iT=\begin{cases}T,&\star_i=f,\\e,&\text{otherwise},\end{cases}
 \qquad
 e\star_iS=\begin{cases}S,&\star_i=g,\\e,&\text{otherwise}.\end{cases}
\]
The rigid upper clone $A_{r,s}=A_e(C_{r,s})$ fails an identity of $D_K$ in
$(r+1)(s+1)$ variables.
\end{proposition}

\begin{corollary}[The ambient native variety]
\label{core:cor:ambient-nfb}
For every $K\geq3$, the variety $\operatorname V(D_K)$ has no identity
basis using a bounded number of variables, and hence no finite identity
basis.
\end{corollary}

\begin{proposition}[A seven-equation basis]\label{core:prop:choice-union-basis}
For every $K\geq3$ and owner $a$, the winner-set algebra in the
signature $\{\star_a,\cup\}$ generates exactly the variety of
meet-distributive bisemilattices. Its identities are therefore
axiomatized by the seven equations just described.
\end{proposition}

\begin{proposition}[Canonical atomic quotients and uniform lifting]
\label{core:prop:atomic-uniform-lift}
The laws $\Gamma_K$ are $K^2+3K+3$ valid core identities, each using at most three
variables. In any model $A$ of these laws and for each $u\in A$,
$q_u$ maps the ideal $A_{\leq u}$ onto its largest quotient in
$\operatorname V(\mathbf A_K^{\rm at})$, with normalized operations
$a\mathbin{\widehat\star_i}b=q_u(a\star_i b)$. Moreover
\begin{equation}\label{core:eq:atomic-closure-meet}
 q_u(x)=\bigwedge_{i\in I}e_i^u(x)\qquad(x\leq u),
\end{equation}
where the greatest lower bound exists even if other meets do not.

Consequently, if $\mathbf A_K^{\rm at}\models s=t$, let $X$ be the
union of the variables of $s,t$ and let $z\notin X$. Then
\begin{equation}\label{core:eq:atomic-bounded-lift}
 \Gamma_K\vdash U\del s=U\del t,
 \qquad U=z+\sum_{x\in X}x.
\end{equation}
In particular, substitution and replacement in core contexts are allowed,
with all resulting variables included in the common bound.
\end{proposition}
